import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://app:app@localhost:5432/mydb'
});

// Middleware: rate limiting (basic, per-IP)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sort, order } = req.query;

    let query = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      query += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist... partially
    const allowedSorts = ['price', 'name', 'created_at'];
    if (sort && allowedSorts.includes(sort)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort} ${direction}`;
    }

    query += ' LIMIT 50';
    const result = await pool.query(query, params);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Admin report endpoint - generates custom reports
app.post('/api/admin/report', async (req, res) => {
  const authToken = req.headers['x-admin-token'];
  const expectedToken = crypto.createHash('sha256')
    .update(process.env.ADMIN_SECRET || 'changeme')
    .digest('hex');

  if (authToken !== expectedToken) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  try {
    const { dimensions, metrics, filters } = req.body;

    // Build report query from user-specified dimensions
    const validDimensions = ['category', 'region', 'quarter'];
    const validMetrics = ['sum(price)', 'count(*)', 'avg(price)'];

    const safeDims = (dimensions || []).filter(d => validDimensions.includes(d));
    const safeMetrics = (metrics || []).filter(m => validMetrics.includes(m));

    if (safeDims.length === 0) safeDims.push('category');
    if (safeMetrics.length === 0) safeMetrics.push('count(*)');

    let reportQuery = `SELECT ${safeDims.join(', ')}, ${safeMetrics.join(', ')} FROM orders`;

    // Apply filters - THIS IS THE VULNERABILITY
    if (filters && typeof filters === 'object') {
      const whereClauses = [];
      for (const [key, value] of Object.entries(filters)) {
        // Intended to only allow known filter keys but check is bypassable
        if (/^[a-z_]+$/.test(key)) {
          whereClauses.push(`${key} = '${value}'`);
        }
      }
      if (whereClauses.length > 0) {
        reportQuery += ` WHERE ${whereClauses.join(' AND ')}`;
      }
    }

    reportQuery += ` GROUP BY ${safeDims.join(', ')}`;

    const result = await pool.query(reportQuery);
    res.json({ report: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed' });
  }
});

